SELECT   WHERE s.tenant_id=#{tenant} AND s.store_id=#{input.storeId} AND s.sku_id>#{input.after}
  AND s.status=#{input.status}AND (LOCATE(LOWER(#{input.q}),LOWER(s.title))>0 OR LOCATE(UPPER(#{input.q}),b.barcode)>0)
  AND p.category_id=#{input.categoryId}AND s.unit_price>=CAST(#{input.minimumPrice} AS DECIMAL(14,2))AND s.unit_price<=CAST(#{input.maximumPrice} AS DECIMAL(14,2)) ORDER BY s.sku_id LIMIT #{input.limit}
